import heapq

def match(orders):
    book = {}      # id -> {'side','price','qty','seq'}
    buy_heap = []  # entries: (-price, seq, id)
    sell_heap = [] # entries: (price, seq, id)
    trades = []
    seq = 0

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        seq += 1
        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                sp, sseq, sid = sell_heap[0]
                if sid not in book or book[sid]['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if typ != 'market' and sp > price:
                    break
                avail = book[sid]['qty']
                traded = min(remaining, avail)
                trades.append([oid, sid, sp, traded])
                remaining -= traded
                book[sid]['qty'] -= traded
                if book[sid]['qty'] == 0:
                    heapq.heappop(sell_heap)
                    del book[sid]

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # sell
            while remaining > 0 and buy_heap:
                bp_neg, bseq, bid = buy_heap[0]
                bp = -bp_neg
                if bid not in book or book[bid]['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if typ != 'market' and bp < price:
                    break
                avail = book[bid]['qty']
                traded = min(remaining, avail)
                trades.append([bid, oid, bp, traded])
                remaining -= traded
                book[bid]['qty'] -= traded
                if book[bid]['qty'] == 0:
                    heapq.heappop(buy_heap)
                    del book[bid]

            if remaining > 0 and typ == 'limit':
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

